import{_ as a,o,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"पूर्व-एशियाई सघन सभ्यता","description":"","frontmatter":{},"headers":[],"relativePath":"hi/31-东亚集约型文明.md","filePath":"hi/31-东亚集约型文明.md","lastUpdated":1789183869000}'),l={name:"hi/31-东亚集约型文明.md"};function e(n,t,d,h,s,u){return o(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="पूर्व-एशियाई-सघन-सभ्यता" tabindex="-1">पूर्व-एशियाई सघन सभ्यता <a class="header-anchor" href="#पूर्व-एशियाई-सघन-सभ्यता" aria-label="Permalink to &quot;पूर्व-एशियाई सघन सभ्यता&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>31</td></tr><tr><td>मॉड्यूल</td><td>सभ्यता-प्रकार और सामाजिक व्यवस्थाएँ</td></tr><tr><td>कीवर्ड</td><td>पूर्व-एशियाई सघन, समूह-प्राथमिकता, विशाल-प्रशिक्षण, कुशल-क्रियान्वयन, पारिवारिक-विरासत</td></tr></tbody></table><h2 id="i-पूर्व-एशियाई-सघन-सभ्यता-की-उत्पत्ति-और-केंद्रीय-विचार" tabindex="-1">I. पूर्व-एशियाई सघन सभ्यता की उत्पत्ति और केंद्रीय-विचार <a class="header-anchor" href="#i-पूर्व-एशियाई-सघन-सभ्यता-की-उत्पत्ति-और-केंद्रीय-विचार" aria-label="Permalink to &quot;I. पूर्व-एशियाई सघन सभ्यता की उत्पत्ति और केंद्रीय-विचार&quot;">​</a></h2><p>पाँच प्रकारों में सर्वाधिक सामूहिकवादी; उत्पत्ति — यथार्थ विश्व के पूर्वी एशिया की सहस्राब्दी परंपराओं में। दीर्घ इतिहास से लक्षण: केंद्र-समूह, आधार-परिवार, नींव-व्यवस्था। सभ्यता-स्थापना के बाद परंपरा + सहजीवन-विचार = &quot;पूर्व-एशियाई सघन सभ्यता&quot;।</p><p>केंद्रीय-विचार आठ अक्षर: &quot;समूह-प्राथमिकता, सघन-दक्षता&quot;:</p><ol><li><strong>समूह-प्राथमिकता</strong>: समूह-हित व्यक्ति-हित से ऊपर; व्यक्ति-विकास समूह-विकास में; परिवार-संप्रदाय-समुदाय मूल कोशिकाएँ; योगदान से मूल्य</li><li><strong>सघन-दक्षता</strong>: समूह-योजना से सघन-कुशल उपयोग; छिटकी-दोहराव का विरोध; बड़े कार्य हेतु बल</li><li><strong>व्यवस्था-सामंजस्य</strong>: श्रेष्ठ-कनिष्ठ क्रम, बड़ों-का-सम्मान; सामाजिक सामंजस्य</li><li><strong>परिश्रम-प्रगति</strong>: मेहनत, मितव्ययिता, दृढ़ता; अथक प्रयास से भाग्य-परिवर्तन</li></ol><p>सभ्यता के केंद्रीय-विचारों से उच्च अनुकूलता: &quot;अधिक परिश्रम, अधिक प्रतिफल&quot;, &quot;स्वयं-वृद्धि&quot;, &quot;हर किसी के लिए पथ&quot;, &quot;दस हजार जातियों की समान प्रगति&quot;। समूह-प्राथमिकता → समान प्रगति; सघनता → दक्षता; परिश्रम → स्वयं-वृद्धि।</p><h2 id="ii-सामाजिक-संरचना" tabindex="-1">II. सामाजिक संरचना <a class="header-anchor" href="#ii-सामाजिक-संरचना" aria-label="Permalink to &quot;II. सामाजिक संरचना&quot;">​</a></h2><p>&quot;परिवार—संप्रदाय—समुदाय&quot; त्रि-स्तरीय समूह — निहित, घनिष्ठ नेटवर्क:</p><table tabindex="0"><thead><tr><th>स्तर</th><th>इकाई</th><th>आकार</th><th>केंद्रीय कार्य</th><th>संसाधन-विधि</th></tr></thead><tbody><tr><td>प्रथम</td><td>परिवार</td><td>दसियों-सैकड़ों</td><td>मूल-जीविका, रक्त-संबंध, आरंभिक-शिक्षा</td><td>आवश्यकता-अनुसार भीतर</td></tr><tr><td>द्वितीय</td><td>संप्रदाय</td><td>सैकड़ों-दसियों हज़ार</td><td>व्यावसायिक प्रशिक्षण, तकनीक-अनुसंधान, संसाधन</td><td>श्रम-अनुसार भीतर</td></tr><tr><td>तृतीय</td><td>समुदाय</td><td>दसियों हज़ार-लाखों</td><td>सार्वजनिक सेवाएँ, अधोसंरचना, शासन</td><td>समन्वय + बाज़ार</td></tr></tbody></table><h3 id="_2-1-परिवार" tabindex="-1">2.1 परिवार <a class="header-anchor" href="#_2-1-परिवार" aria-label="Permalink to &quot;2.1 परिवार&quot;">​</a></h3><p>सबसे मूल इकाई, रक्त-संबंधी दसियों-सैकड़ों:</p><ul><li><strong>मूल-जीविका</strong>: पारस्परिक सहायता</li><li><strong>रक्त-संबंध</strong>: रीति-समारोह, मिलन</li><li><strong>आरंभिक-शिक्षा</strong>: बड़े छोटों को — ज्ञान, साधना-प्रवेश, चरित्र</li><li><strong>संचय</strong>: साझा धन-संसाधन</li></ul><p>सिद्धांत &quot;आवश्यकता + श्रम&quot;: मूल आवश्यकता-अनुसार; अतिरिक्त संसाधन-पुरस्कार योगदान-अनुसार।</p><h3 id="_2-2-संप्रदाय" tabindex="-1">2.2 संप्रदाय <a class="header-anchor" href="#_2-2-संप्रदाय" aria-label="Permalink to &quot;2.2 संप्रदाय&quot;">​</a></h3><p>व्यावसायिक-प्रशिक्षण-तकनीकी-अनुसंधान का केंद्र, सैकड़ों-दसियों हज़ार:</p><ul><li><strong>प्रशिक्षण</strong>: पूर्ण प्रणाली, गुरु-दल</li><li><strong>अनुसंधान</strong>: साधना-अभियांत्रिकी तकनीक</li><li><strong>संसाधन</strong>: संचालन-सेवाओं से आय</li><li><strong>प्रतिभा-निर्गम</strong>: उच्च संस्थानों में</li></ul><p>वितरण &quot;श्रम-प्रधान&quot;: उपलब्धि-योगदान-अनुसार। कठोर सोपान: बाह्य, आंतरिक, केंद्रीय शिष्य, वरिष्ठ, प्रमुख।</p><h3 id="_2-3-समुदाय" tabindex="-1">2.3 समुदाय <a class="header-anchor" href="#_2-3-समुदाय" aria-label="Permalink to &quot;2.3 समुदाय&quot;">​</a></h3><p>उच्चतम इकाई, दसियों हज़ार-लाखों:</p><ul><li><strong>सेवाएँ</strong>: शिक्षा, चिकित्सा, आवास, पर्यावरण</li><li><strong>अधोसंरचना</strong>: लंगर, ऊर्जा-चैनल, परिवहन</li><li><strong>शासन</strong>: व्यवस्था, विवाद-निपटान, कानून</li><li><strong>समन्वय</strong>: क्षेत्रीय संसाधन-समग्र</li></ul><p>सिद्धांत &quot;समन्वय + बाज़ार&quot;।</p><h2 id="iii-साधना-मॉडल" tabindex="-1">III. साधना-मॉडल <a class="header-anchor" href="#iii-साधना-मॉडल" aria-label="Permalink to &quot;III. साधना-मॉडल&quot;">​</a></h2><p>&quot;विशाल, मानकीकृत, व्यवस्थित&quot;:</p><h3 id="_3-1-विशाल-प्रशिक्षण" tabindex="-1">3.1 विशाल प्रशिक्षण <a class="header-anchor" href="#_3-1-विशाल-प्रशिक्षण" aria-label="Permalink to &quot;3.1 विशाल प्रशिक्षण&quot;">​</a></h3><p>संप्रदाय एक साथ दसियों हज़ार शिष्य; मानक पाठ्यक्रम, असेंबली-लाइन शिक्षण। लाभ: दक्षता, व्यापकता, तीव्र उन्नति।</p><h3 id="_3-2-मानकीकरण" tabindex="-1">3.2 मानकीकरण <a class="header-anchor" href="#_3-2-मानकीकरण" aria-label="Permalink to &quot;3.2 मानकीकरण&quot;">​</a></h3><p>तीन सौ मूल प्रणालियाँ पाठ्यपुस्तकों-पाठ्यक्रम-मानकों में; हर चरण स्पष्ट लक्ष्य-माप।</p><h3 id="_3-3-गुरु-शिष्य-परंपरा" tabindex="-1">3.3 गुरु-शिष्य परंपरा <a class="header-anchor" href="#_3-3-गुरु-शिष्य-परंपरा" aria-label="Permalink to &quot;3.3 गुरु-शिष्य परंपरा&quot;">​</a></h3><p>विशालता के बावजूद गुरु-शिष्य महत्वपूर्ण; हर शिष्य को गुरु; प्रतिभाशाली — &quot;निजी-शिष्य&quot;, एकांतिक मार्गदर्शन। &quot;विशाल + व्यक्तिगत&quot;।</p><h3 id="_3-4-मूल्यांकन-पदोन्नति" tabindex="-1">3.4 मूल्यांकन-पदोन्नति <a class="header-anchor" href="#_3-4-मूल्यांकन-पदोन्नति" aria-label="Permalink to &quot;3.4 मूल्यांकन-पदोन्नति&quot;">​</a></h3><p>कठोर: स्तर, युद्ध-क्षमता, सिद्धांत, चरित्र। सफल — पदोन्नति-संसाधन-प्रतिष्ठा; असफल — पुनरावृत्ति, बहिष्कार। प्रेरणा + गुणवत्ता।</p><h2 id="iv-उत्पादन-आधारित-अनुबंध-तंत्र" tabindex="-1">IV. उत्पादन-आधारित अनुबंध तंत्र <a class="header-anchor" href="#iv-उत्पादन-आधारित-अनुबंध-तंत्र" aria-label="Permalink to &quot;IV. उत्पादन-आधारित अनुबंध तंत्र&quot;">​</a></h2><p>&quot;सामूहिक-अनुबंध&quot; प्रधान:</p><ol><li><strong>अनुबंध-इकाई</strong>: परिवार-संप्रदाय, व्यक्ति नहीं</li><li><strong>सामग्री</strong>: क्षेत्रीय संसाधन-विकास, लंगर-रखरखाव, अनुसंधान — समुदाय से</li><li><strong>आंतरिक-वितरण</strong>: द्वितीयक — समूह-संचय + व्यक्ति-प्रतिफल</li><li><strong>संयुक्त-दायित्व</strong>: एक का यश — समूह को पुरस्कार; एक का उल्लंघन — समूह-रेटिंग</li></ol><p>लाभ: पैमाना-प्रभाव, सहयोग, दक्षता; संगठन-अपनापन।</p><h2 id="v-लाभ-और-चुनौतियाँ" tabindex="-1">V. लाभ और चुनौतियाँ <a class="header-anchor" href="#v-लाभ-और-चुनौतियाँ" aria-label="Permalink to &quot;V. लाभ और चुनौतियाँ&quot;">​</a></h2><h3 id="_5-1-विशिष्ट-लाभ" tabindex="-1">5.1 विशिष्ट-लाभ <a class="header-anchor" href="#_5-1-विशिष्ट-लाभ" aria-label="Permalink to &quot;5.1 विशिष्ट-लाभ&quot;">​</a></h3><ul><li><strong>क्रियान्वयन</strong>: परंपरा + सोपान — तीव्र निर्णय</li><li><strong>दक्षता</strong>: सघनता + विशालता</li><li><strong>संगठन</strong>: परिवार-संप्रदाय घनिष्ठता</li><li><strong>स्थिरता</strong>: व्यवस्था + सामंजस्य</li></ul><h3 id="_5-2-चुनौतियाँ" tabindex="-1">5.2 चुनौतियाँ <a class="header-anchor" href="#_5-2-चुनौतियाँ" aria-label="Permalink to &quot;5.2 चुनौतियाँ&quot;">​</a></h3><ul><li><strong>व्यक्ति-स्थान</strong>: समूह-अति से स्वतंत्रता-रचनात्मकता दबना</li><li><strong>दुर्बल-नवाचार</strong>: मानकीकरण से सोच-सीमा</li><li><strong>वर्ग-जड़ता-जोखिम</strong>: गतिशीलता-विहीन सोपान</li><li><strong>प्रतिस्पर्धा-दबाव</strong>: कठोर परीक्षाएँ</li></ul><p>समाधान: अन्य प्रकारों के लाभ — उत्तर-अमेरिकी नवाचार-प्रोत्साहन, उत्तर-यूरोपीय मनोवैज्ञानिक-सहारा।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>सर्वाधिक सामूहिकवादी प्रकार: &quot;समूह-प्राथमिकता, सघन-दक्षता&quot;; परिवार—संप्रदाय—समुदाय; विशाल-मानकीकृत साधना; सामूहिक-अनुबंध — कुशल विकास व प्रबल संगठन। अपनी विशेषता सँभाले, अन्य के लाभ लेता — संतुलित-समावेशी दिशा में।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>30-五种共生文明分型总览 (पाँच सहजीवी सभ्यता-प्रकारों का समग्र अवलोकन)</li><li>36-社会结构与阶层流动 (सामाजिक संरचना और वर्ग-गतिशीलता)</li><li>37-共生教育体系 (सहजीवी शिक्षा प्रणाली)</li></ul>',46)])])}const p=a(l,[["render",e]]);export{g as __pageData,p as default};
